algorithm CountWeekendDays
    define count as integer;
    define i as integer;
    define day as integer;
    define total as integer;
    read count;
    total <- 0;
    for i <- 1 to count step 1 do
        read day;
        if day = 6 or day = 7 then
            total <- total + 1;
        endIf
    endFor
    write total;
endAlgorithm
